workspace.definitionText:
dimension: subscription_start_dt {
  label: "dates"
  type: date
  sql: date(${subscription_records.subscription_start_ts}) ;;
}

dimension: state {
  label: "geography"
  type: string
  sql: ${user_records.state} ;;
}

dimension: city {
  label: "geography"
  type: string
  sql: ${user_records.city} ;;
}

dimension: dob {
  label: "demographic"
  type: string
  sql: ${user_records.dob} ;;
}

dimension: subscription_type {
  label: "subscription"
  type: string
  sql: ${subscription_records.subscription_type} ;;
}

dimension: subscription_status {
  label: "subscription"
  type: string
  sql: ${subscription_records.subscription_status} ;;
}

dimension: cancel_status {
  label: "subscription"
  type: string
  sql: ${subscription_records.cancel_status} ;;
}

dimension: payment_processor {
  label: "payment"
  type: string
  sql: ${transaction_records.payment_processor} ;;
}

dimension: card_brand {
  label: "payment"
  type: string
  sql: ${transaction_records.card_brand} ;;
}

dimension: subscription_length {
  label: "subscription"
  type: string
  sql: ${subscription_records.subscription_length} ;;
}

dimension: payment_status {
  label: "scheduled"
  type: string
  sql: ${scheduled_subscription_payment_records.payment_status} ;;
}

dimension: renewal_number {
  label: "scheduled"
  type: string
  sql: ${scheduled_subscription_payment_records.renewal_number} ;;
}

measure: gross_revenue {
  label: "revenue"
  type: sum
  sql: ${transaction_records.gross_amount} ;;
  value_format: currency
}

measure: net_revenue {
  label: "revenue"
  type: sum
  sql: ${transaction_records.net_amount} ;;
  value_format: currency
}

measure: total_subscriptions {
  label: "subscription"
  type: sum
  sql: case when ${subscription_records.subscription_type} in ('new_subscription','reactivation') then 1 else 0 end ;;
  value_format: numeric
}

measure: new_subscriptions {
  label: "subscription"
  type: sum
  sql: case when ${subscription_records.subscription_type}='new_subscription' then 1 else 0 end ;;
  value_format: numeric
}

measure: reactivations {
  label: "subscription"
  type: sum
  sql: case when ${subscription_records.subscription_type}='reactivation' then 1 else 0 end ;;
  value_format: numeric
}

measure: active_subscriptions {
  label: "subscription"
  type: sum
  sql: case when ${subscription_records.subscription_status}='active' then 1 else 0 end ;;
  value_format: numeric
}

measure: cancelled_subscriptions {
  label: "subscription"
  type: sum
  sql: case when ${subscription_records.subscription_status}='cancelled' then 1 else 0 end ;;
  value_format: numeric
}

measure: pending_cancellation_subscriptions {
  label: "subscription"
  type: sum
  sql: case when ${subscription_records.subscription_status}='pending_cancellation' then 1 else 0 end ;;
  value_format: numeric
}

measure: percent_reactivations {
  label: "subscription"
  type: number
  sql: {{reactivations}} / {{total_subscriptions}} ;;
  value_format: percent
}

measure: percent_new_subscriptions {
  label: "subscription"
  type: number
  sql: {{new_subscriptions}} / {{total_subscriptions}} ;;
  value_format: percent
}

measure: percent_cancelled_subscriptions {
  label: "subscription"
  type: number
  sql: {{cancelled_subscriptions}} / {{total_subscriptions}} ;;
  value_format: percent
}

measure: percent_pending_cancellation_subscriptions {
  label: "subscription"
  type: number
  sql: {{pending_cancellation_subscriptions}} / {{total_subscriptions}} ;;
  value_format: percent
}

measure: percent_active_subscriptions {
  label: "subscription"
  type: number
  sql: {{active_subscriptions}} / {{total_subscriptions}} ;;
  value_format: percent
}

measure: discounts {
  label: "revenue"
  type: sum
  sql: ${transaction_records.discount_amount} ;;
  value_format: currency
}

measure: scheduled_gross_revenue {
  label: "scheduled"
  type: sum
  sql: ${scheduled_subscription_payment_records.gross_amount} ;;
  value_format: currency
}

measure: scheduled_discounts {
  label: "scheduled"
  type: sum
  sql: ${scheduled_subscription_payment_records.discount_amount} ;;
  value_format: currency
}

measure: scheduled_net_revenue {
  label: "scheduled"
  type: sum
  sql: ${scheduled_subscription_payment_records.scheduled_amount} ;;
  value_format: currency
}

measure: total_renewals {
  label: "scheduled"
  type: sum
  sql: case when ${scheduled_subscription_payment_records.payment_status} in ('paid','scheduled') then 1 else 0 end ;;
  value_format: numeric
}

measure: scheduled_taxes {
  label: "scheduled"
  type: sum
  sql: ${scheduled_subscription_payment_records.tax_amount} ;;
  value_format: currency
}

measure: paid_renewals {
  label: "scheduled"
  type: sum
  sql: case when ${scheduled_subscription_payment_records.payment_status}='paid' then 1 else 0 end ;;
  value_format: numeric
}

measure: scheduled_renewals {
  label: "scheduled"
  type: sum
  sql: case when ${scheduled_subscription_payment_records.payment_status}='scheduled' then 1 else 0 end ;;
  value_format: numeric
}

dimension: signup_date {
  label: "dates"
  type: date
  sql: date(${user_records.signup_ts}) ;;
}

dimension: trial_start_date {
  label: "dates"
  type: date
  sql: date(${subscription_records.trial_start_ts}) ;;
}

dimension: first_payment_date {
  label: "dates"
  type: date
  sql: date(${subscription_records.subscription_start_ts}) ;;
}

dimension: cancellation_date {
  label: "dates"
  type: date
  sql: date(${subscription_records.subscription_end_ts}) ;;
}

dimension: transaction_date {
  label: "dates"
  type: date
  sql: date(${transaction_records.transaction_ts}) ;;
}

dimension: scheduled_payment_date {
  label: "dates"
  type: date
  sql: date(${scheduled_subscription_payment_records.scheduled_payment_ts}) ;;
}

dimension: signup_cohort_month {
  label: "cohorts"
  type: date
  sql: date_trunc('month', ${user_records.signup_ts}) ;;
}

dimension: signup_cohort_year {
  label: "cohorts"
  type: date
  sql: date_trunc('year', ${user_records.signup_ts}) ;;
}

dimension: campaign_source {
  label: "acquisition"
  type: string
  sql: ${user_records.campaign_source} ;;
}

dimension: campaign_name {
  label: "acquisition"
  type: string
  sql: ${user_records.campaign_name} ;;
}

dimension: plan_name {
  label: "subscription"
  type: string
  sql: case when ${subscription_records.subscription_length}=1 then '1 month' when ${subscription_records.subscription_length}=3 then '3 month' when ${subscription_records.subscription_length}=12 then '12 month' else 'other' end ;;
}

dimension: customer_age_band {
  label: "demographic"
  type: string
  sql: case when datediff('year', ${user_records.dob}, current_date()) < 25 then '18-24' when datediff('year', ${user_records.dob}, current_date()) < 35 then '25-34' when datediff('year', ${user_records.dob}, current_date()) < 45 then '35-44' when datediff('year', ${user_records.dob}, current_date()) < 55 then '45-54' when datediff('year', ${user_records.dob}, current_date()) < 65 then '55-64' else '65+' end ;;
}

dimension: tenure_bucket {
  label: "customer lifecycle"
  type: string
  sql: case when datediff('day', ${user_records.signup_ts}, current_date()) < 30 then '0-29 days' when datediff('day', ${user_records.signup_ts}, current_date()) < 90 then '30-89 days' when datediff('day', ${user_records.signup_ts}, current_date()) < 180 then '90-179 days' when datediff('day', ${user_records.signup_ts}, current_date()) < 365 then '180-364 days' else '365+ days' end ;;
}

dimension: transaction_type {
  label: "payments"
  type: string
  sql: ${transaction_records.transaction_type} ;;
}

dimension: payment_method {
  label: "payments"
  type: string
  sql: ${transaction_records.credit_or_debit} ;;
}

dimension: failure_reason {
  label: "payments"
  type: string
  sql: ${failed_transactions.fail_error} ;;
}

dimension: subscription_change_reason {
  label: "subscription"
  type: string
  sql: ${subscription_change_records.change_reason} ;;
}

measure: new_users {
  label: "acquisition"
  type: count_distinct
  sql: ${user_records.user_id} ;;
  value_format: numeric
}

measure: unique_subscribers {
  label: "subscription"
  type: count_distinct
  sql: ${subscription_records.subscription_id} ;;
  value_format: numeric
}

measure: upgrades {
  label: "subscription changes"
  type: sum
  sql: case when ${subscription_change_records.change_reason}='upgrade' then 1 else 0 end ;;
  value_format: numeric
}

measure: downgrades {
  label: "subscription changes"
  type: sum
  sql: case when ${subscription_change_records.change_reason}='downgrade' then 1 else 0 end ;;
  value_format: numeric
}

measure: upgrade_charges {
  label: "revenue details"
  type: sum
  sql: case when ${transaction_records.transaction_type}='upgrade_charge' then ${transaction_records.gross_amount} else 0 end ;;
  value_format: currency
}

measure: downgrade_refunds {
  label: "revenue details"
  type: sum
  sql: case when ${transaction_records.transaction_type}='downgrade_refund' then ${transaction_records.refund_amount} else 0 end ;;
  value_format: currency
}

measure: cancellation_refunds {
  label: "revenue details"
  type: sum
  sql: case when ${transaction_records.transaction_type}='general_refund' then ${transaction_records.refund_amount} else 0 end ;;
  value_format: currency
}

measure: total_refunds {
  label: "revenue details"
  type: sum
  sql: ${transaction_records.refund_amount} ;;
  value_format: currency
}

measure: total_taxes {
  label: "revenue details"
  type: sum
  sql: ${transaction_records.tax_amount} ;;
  value_format: currency
}

measure: total_chargebacks {
  label: "revenue details"
  type: sum
  sql: ${transaction_records.chargeback_amount} ;;
  value_format: currency
}

measure: one_time_purchase_revenue {
  label: "revenue details"
  type: sum
  sql: case when ${transaction_records.transaction_type}='one_time_purchase' then ${transaction_records.net_amount} else 0 end ;;
  value_format: currency
}

measure: successful_payment_transactions {
  label: "payments"
  type: sum
  sql: case when ${transaction_records.transaction_type} in ('new_subscription','renewal','upgrade_charge','one_time_purchase') then 1 else 0 end ;;
  value_format: numeric
}

measure: failed_payment_attempts {
  label: "payments"
  type: count_distinct
  sql: ${failed_transactions.failed_transaction_id} ;;
  value_format: numeric
}

measure: eligible_recurring_payments {
  label: "renewals"
  type: sum
  sql: case when ${scheduled_subscription_payment_records.renewal_number}>1 and ${scheduled_subscription_payment_records.payment_status} in ('paid','past_due','cancelled') then 1 else 0 end ;;
  value_format: numeric
}

measure: successful_recurring_payments {
  label: "renewals"
  type: sum
  sql: case when ${scheduled_subscription_payment_records.renewal_number}>1 and ${scheduled_subscription_payment_records.payment_status}='paid' then 1 else 0 end ;;
  value_format: numeric
}

measure: failed_recurring_payments {
  label: "renewals"
  type: sum
  sql: case when ${scheduled_subscription_payment_records.renewal_number}>1 and ${scheduled_subscription_payment_records.payment_status} in ('past_due','cancelled') then 1 else 0 end ;;
  value_format: numeric
}

measure: marketing_spend {
  label: "marketing"
  type: sum
  sql: ${marketing_records.cost} ;;
  value_format: currency
}

measure: marketing_views {
  label: "marketing"
  type: sum
  sql: ${marketing_records.views} ;;
  value_format: numeric
}

measure: marketing_clicks {
  label: "marketing"
  type: sum
  sql: ${marketing_records.clicks} ;;
  value_format: numeric
}

measure: marketing_visits {
  label: "marketing"
  type: sum
  sql: ${marketing_records.visits} ;;
  value_format: numeric
}

measure: discount_value {
  label: "revenue details"
  type: sum
  sql: abs(${transaction_records.discount_amount}) ;;
  value_format: currency
}

measure: refund_value {
  label: "revenue details"
  type: sum
  sql: abs(${transaction_records.refund_amount}) ;;
  value_format: currency
}

measure: transaction_count {
  label: "payments"
  type: count_distinct
  sql: ${transaction_records.transaction_id} ;;
  value_format: numeric
}

measure: average_customer_tenure_days {
  label: "customer value"
  type: avg
  sql: datediff('day', ${user_records.signup_ts}, current_date()) ;;
  value_format: numeric
}

measure: recurring_payment_success_rate {
  label: "renewals"
  type: number
  sql: {{successful_recurring_payments}} / {{eligible_recurring_payments}} ;;
  value_format: percent
}

measure: recurring_payment_failure_rate {
  label: "renewals"
  type: number
  sql: {{failed_recurring_payments}} / {{eligible_recurring_payments}} ;;
  value_format: percent
}

measure: cancellation_rate {
  label: "subscription"
  type: number
  sql: {{cancelled_subscriptions}} / {{total_subscriptions}} ;;
  value_format: percent
}

measure: upgrade_rate {
  label: "subscription changes"
  type: number
  sql: {{upgrades}} / {{total_subscriptions}} ;;
  value_format: percent
}

measure: discount_rate {
  label: "revenue details"
  type: number
  sql: {{discount_value}} / {{gross_revenue}} ;;
  value_format: percent
}

measure: refund_rate {
  label: "revenue details"
  type: number
  sql: {{refund_value}} / {{gross_revenue}} ;;
  value_format: percent
}

measure: marketing_cost_per_new_user {
  label: "marketing"
  type: number
  sql: {{marketing_spend}} / {{new_users}} ;;
  value_format: currency
}

measure: cost_per_click {
  label: "marketing"
  type: number
  sql: {{marketing_spend}} / {{marketing_clicks}} ;;
  value_format: currency
}

measure: marketing_click_through_rate {
  label: "marketing"
  type: number
  sql: {{marketing_clicks}} / {{marketing_views}} ;;
  value_format: percent
}

measure: observed_customer_ltv {
  label: "customer value"
  type: number
  sql: {{net_revenue}} / {{new_users}} ;;
  value_format: currency
}

workspace.evaluationText:
measure: pending_cancellation_subscriptions {
  label: "subscription"
  type: sum
  sql: case when ${subscription_records.subscription_status}='pending_cancellation' then 1 else 0 end ;;
  value_format: numeric
}
